 "content": "from collections import Counter

def transform(grid):
    """Restore masked cells from diagonal symmetry and matching visible patches."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    used = set()
    # A diagonally symmetric pair can be recovered directly whenever its mate is visible.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6 and grid[c][r] != 6:
                out[r][c] = grid[c][r]
                used.add((r, c))

    # For mutually masked transposed pairs, match the visible context to every
    # unmasked cell's neighborhood and vote among the best patch matches.
    for r in range(h):
        for c in range(r, w):
            if grid[r][c] != 6 or grid[c][r] != 6 or (r, c) in used:
                continue
            scores = Counter()
            for y in range(h):
                for x in range(w):
                    if grid[y][x] == 6:
                        continue
                    score = 0.0
                    total = 0.0
