    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    def orbit(r, c):
        seen = {(r, c)}
        stack = [(r, c)]
        while stack:
            y, x = stack.pop()
            # Main-diagonal transpose plus the two symmetry axes of the
            # 28x28 patterned interior (rows/cols 2..29, reflection sum 31).
            for yy, xx in ((x, y), (31-y, x), (y, 31-x)):
                if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen:
                    seen.add((yy, xx))
                    stack.append((yy, xx))
        return seen

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6:
                for y, x in orbit(r, c):
                    if grid[y][x] != 6:
                        out[r][c] = grid[y][x]
                        break
    return out

